// SPDX-License-Identifier: Unlicensed
pragma solidity >=0.8.0;
library L { event E(uint256 x); function f(uint256 x) external { emit E(x); } }
contract C {
    uint256 immutable a;
    address immutable b;
    constructor(uint256 x) { a = x; b = msg.sender; }
    function g(uint256 x) external returns (uint256) { require(msg.sender == b); L.f(x); return a + x; }
    function h() external view returns (uint256) { return a; }
}
